using System.Data;
using Essco.Application.Payroll;
using Microsoft.Data.SqlClient;
namespace Essco.Infrastructure.Data;

public sealed class SqlServerPayrollBankRepository(string connectionString, int timeout) : IPayrollBankRepository
{ public async ValueTask<PayrollBankBatch?> GetAsync(int number, DateOnly date, CancellationToken t) { await using var c = new SqlConnection(connectionString); await c.OpenAsync(t); PayrollBankHeader? h; await using (var cmd = Cmd("SELECT [Consecutivo],[Cedula_Empresa],[Nombre_Empresa],[CuentaDeducirPlanilla],[Comentario] FROM [dbo].[Planilla] WHERE [Consecutivo]=@Number", c)) { cmd.Parameters.Add("@Number", SqlDbType.Int).Value = number; await using var r = await cmd.ExecuteReaderAsync(t); h = await r.ReadAsync(t) ? new(number, S(r, 1), S(r, 2), S(r, 3), S(r, 4), date) : null; } if (h is null) return null; var items = new List<PayrollBankMovement>(); await using (var cmd = Cmd("SELECT [CuentaBancaria],[Salario_Final],[Nombre],[Cedula],[IdColaborador] FROM [dbo].[Planilla_Empleados] WHERE [Id_Planilla]=@Number ORDER BY [Nombre]", c)) { cmd.Parameters.Add("@Number", SqlDbType.Int).Value = number; await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) items.Add(new(S(r, 0), r.IsDBNull(1) ? 0 : r.GetDecimal(1), S(r, 2), S(r, 3), S(r, 4))); } return new(h, items); } private SqlCommand Cmd(string sql, SqlConnection c) => new(sql, c) { CommandTimeout = timeout }; private static string S(SqlDataReader r, int i) => r.IsDBNull(i) ? "" : Convert.ToString(r.GetValue(i))?.Trim() ?? ""; }
